from fractions import Fraction


def _det_int(rows, n):
    """Bareiss fraction-free elimination for integer matrices (exact)."""
    sign = 1
    prev = 1
    for k in range(n - 1):
        if rows[k][k] == 0:
            for i in range(k + 1, n):
                if rows[i][k] != 0:
                    rows[k], rows[i] = rows[i], rows[k]
                    sign = -sign
                    break
            else:
                return 0
        pivot = rows[k][k]
        for i in range(k + 1, n):
            for j in range(k + 1, n):
                rows[i][j] = (rows[i][j] * pivot - rows[i][k] * rows[k][j]) // prev
            rows[i][k] = 0
        prev = pivot
    return rows[n - 1][n - 1] * sign


def _det_exact(rows, n):
    """Gaussian elimination with exact Fraction arithmetic."""
    sign = 1
    for k in range(n):
        if rows[k][k] == 0:
            for i in range(k + 1, n):
                if rows[i][k] != 0:
                    rows[k], rows[i] = rows[i], rows[k]
                    sign = -sign
                    break
            else:
                return Fraction(0)
        inv = rows[k][k]
        for i in range(k + 1, n):
            f = rows[i][k] / inv
            if f:
                for j in range(k, n):
                    rows[i][j] -= f * rows[k][j]
    det = Fraction(1)
    for k in range(n):
        det *= rows[k][k]
    return det * sign


def solve(matrix):
    """Determinant of a square integer matrix, as an int. Empty matrix -> 1."""
    if not matrix:
        return 1
    n = len(matrix)
    if all(len(r) == 0 for r in matrix):
        return 1  # degenerate empty matrix
    if all(isinstance(x, int) for r in matrix for x in r):
        det = _det_int([list(r) for r in matrix], n)
        return int(det)
    rows = []
    for r in matrix:
        conv = []
        for x in r:
            try:
                conv.append(Fraction(x))
            except TypeError:
                conv.append(Fraction(int(x)))
        rows.append(conv)
    det = _det_exact(rows, n)
    if det.denominator == 1:
        return int(det)
    return det

