def solve(a: str, b: str) -> int:
    """Compute the Levenshtein (edit) distance between strings *a* and *b*.
    Operations allowed: insertion, deletion, substitution, each costing 1.
    """
    n, m = len(a), len(b)
    # Ensure the shorter string is b to use O(min) space if desired, but simplicity: full DP.
    dp = [[0] * (m + 1) for _ in range(n + 1)]
    for i in range(n + 1):
        dp[i][0] = i
    for j in range(m + 1):
        dp[0][j] = j
    for i in range(1, n + 1):
        ai = a[i - 1]
        for j in range(1, m + 1):
            if ai == b[j - 1]:
                dp[i][j] = dp[i - 1][j - 1]
            else:
                dp[i][j] = 1 + min(dp[i - 1][j],    # deletion
                                   dp[i][j - 1],    # insertion
                                   dp[i - 1][j - 1])  # substitution
    return dp[n][m]

