def solve(tokens):
    """Evaluate Reverse Polish Notation expression.
    tokens: list of strings, each either an integer or one of '+','-','*','/'.
    Division truncates toward zero as in int(a/b) in Python 3.
    """
    stack = []
    for token in tokens:
        if token in ('+', '-', '*', '/'):
            b = stack.pop()
            a = stack.pop()
            if token == '+':
                stack.append(a + b)
            elif token == '-':
                stack.append(a - b)
            elif token == '*':
                stack.append(a * b)
            else:  # division
                # truncate toward zero
                if b == 0:
                    raise ZeroDivisionError('division by zero')
                res = int(a / b)  # Python truncates toward zero for int()
                stack.append(res)
        else:
            stack.append(int(token))
    return stack[-1] if stack else 0

