def solve(s):
    n = len(s)
    if n == 0:
        return ''
    best_start, best_len = 0, 1
    for i in range(n):
        # odd-length centers
        l, r = i, i
        while l >= 0 and r < n and s[l] == s[r]:
            l -= 1
            r += 1
        start, length = l + 1, r - l - 1
        if length > best_len:
            best_start, best_len = start, length
        # even-length centers
        l, r = i, i + 1
        while l >= 0 and r < n and s[l] == s[r]:
            l -= 1
            r += 1
        start, length = l + 1, r - l - 1
        if length > best_len:
            best_start, best_len = start, length
    return s[best_start:best_start + best_len]

