def solve(grid):
    # Validate grid structure
    if not grid:
        return -1
    # Ensure each row is a list
    if any(not isinstance(row, list) for row in grid):
        return -1
    n = len(grid)
    # Find destination: last row's last element if exists
    # If last row empty, no valid destination
    if len(grid[-1]) == 0:
        return -1
    dest_i = n - 1
    dest_j = len(grid[dest_i]) - 1
    # Validate start cell exists
    if len(grid[0]) == 0:
        return -1
    # Helper to check if a cell is open (value == 0)
    def is_open(i, j):
        try:
            return grid[i][j] == 0
        except Exception:
            return False
    # Start or destination blocked
    if not is_open(0, 0) or not is_open(dest_i, dest_j):
        return -1
    from collections import deque
    q = deque()
    q.append((0, 0, 0))
    visited = {(0, 0)}
    while q:
        i, j, d = q.popleft()
        if i == dest_i and j == dest_j:
            return d
        for di, dj in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            ni, nj = i + di, j + dj
            # check row bounds
            if ni < 0 or ni >= n:
                continue
            # check column bounds for this row
            if nj < 0 or nj >= len(grid[ni]):
                continue
            if (ni, nj) in visited:
                continue
            if is_open(ni, nj):
                visited.add((ni, nj))
                q.append((ni, nj, d + 1))
    return -1

